svg.script:
/**/
(function(){
  var root=document.getElementById("az-root");
  if(!root||root.__az)return; root.__az=1;
  var NS="http://www.w3.org/2000/svg";
  var vb=root.viewBox.baseVal;
  var fs=Math.max(12,Math.round(vb.width/88));
  var lh=Math.round(fs*1.34), pad=Math.round(fs*0.72);
  var live=document.getElementById("az-live");
  var tip=document.createElementNS(NS,"g");
  tip.setAttribute("pointer-events","none"); tip.setAttribute("aria-hidden","true"); tip.style.opacity="0";
  var box=document.createElementNS(NS,"rect"); box.setAttribute("rx",String(Math.round(fs*0.55))); box.setAttribute("class","az-tipbox");
  var txt=document.createElementNS(NS,"text"); txt.setAttribute("class","az-tiptxt"); txt.setAttribute("font-size",String(fs));
  tip.appendChild(box); tip.appendChild(txt); root.appendChild(tip);
  var active=null;
  function toRoot(cx,cy){var m=root.getScreenCTM(); if(!m)return{x:cx,y:cy}; var p=root.createSVGPoint(); p.x=cx; p.y=cy; return p.matrixTransform(m.inverse());}
  function build(hz){
    while(txt.firstChild)txt.removeChild(txt.firstChild);
    var lines=(hz.getAttribute("data-tip")||"").split("|");
    for(var i=0;i<lines.length;i++){
      var t=document.createElementNS(NS,"tspan");
      t.setAttribute("x",String(pad)); t.setAttribute("y",String(Math.round(pad+fs*0.95+i*lh)));
      if(i===0)t.setAttribute("class","az-tiptitle");
      t.textContent=lines[i]; txt.appendChild(t);
    }
    var b=txt.getBBox(); tip._w=b.x+b.width+pad; tip._h=lines.length*lh+pad*2;
    box.setAttribute("width",String(Math.round(tip._w))); box.setAttribute("height",String(Math.round(tip._h)));
  }
  function r1(v){return Math.round(v*10)/10;}
  function place(px,py){
    var w=tip._w,h=tip._h,x=px+fs*1.1,y=py-h-fs*0.5;
    if(x+w>vb.x+vb.width)x=px-w-fs*1.1;
    if(x<vb.x+4)x=vb.x+4;
    if(y<vb.y+4)y=py+fs*1.2;
    if(y+h>vb.y+vb.height)y=vb.y+vb.height-h-4;
    tip.setAttribute("transform","translate("+r1(x)+","+r1(y)+")");
  }
  function show(hz,px,py){active=hz; root.setAttribute("data-lit",hz.getAttribute("data-link")||""); build(hz); tip.style.opacity="1"; place(px,py);}
  function hide(){active=null; root.removeAttribute("data-lit"); tip.style.opacity="0";}
  var zs=root.querySelectorAll("[data-tip]");
  for(var k=0;k<zs.length;k++){(function(hz){
    if(!hz.hasAttribute("tabindex"))hz.setAttribute("tabindex","0");
    if(!hz.hasAttribute("role"))hz.setAttribute("role","button");
    hz.setAttribute("aria-label",hz.getAttribute("data-label")||(hz.getAttribute("data-tip")||"").split("|")[0]);
    hz.addEventListener("pointerenter",function(e){var p=toRoot(e.clientX,e.clientY); show(hz,p.x,p.y);});
    hz.addEventListener("pointermove",function(e){if(active===hz){var p=toRoot(e.clientX,e.clientY); place(p.x,p.y);}});
    hz.addEventListener("pointerleave",function(){if(active===hz)hide();});
    hz.addEventListener("pointerdown",function(e){var p=toRoot(e.clientX,e.clientY); show(hz,p.x,p.y);});
    hz.addEventListener("focus",function(){var b=hz.getBoundingClientRect(); var p=toRoot(b.left+b.width/2,b.top+6); show(hz,p.x,p.y);});
    hz.addEventListener("blur",function(){if(active===hz)hide();});
  })(zs[k]);}
  root.addEventListener("pointerleave",hide);
  var MLIVE={
    sano:"Encéfalo saudável em corte coronal: sulcos estreitos, ventrículos finos e o hipocampo cheio no lobo temporal medial.",
    alz:"Encéfalo com Alzheimer: sulcos afundados, córtex adelgaçado e ventrículos dilatados por hidrocefalia ex-vacuo, com o hipocampo retraído em destaque."
  };
  function setMacro(v){
    var s=document.getElementById("az-brain-sano"), a=document.getElementById("az-brain-alz");
    if(s)s.style.display=(v==="sano")?"":"none";
    if(a)a.style.display=(v==="alz")?"":"none";
    var bs=root.querySelectorAll('[data-grp="macro"]');
    for(var i=0;i<bs.length;i++){ if(bs[i].getAttribute("data-val")===v)bs[i].setAttribute("data-on","1"); else bs[i].removeAttribute("data-on"); }
    root.setAttribute("data-macro",v);
    if(live)live.textContent=MLIVE[v]||"";
  }
  var mbs=root.querySelectorAll('[data-grp="macro"]');
  for(var m=0;m<mbs.length;m++){(function(el){
    var v=el.getAttribute("data-val");
    el.addEventListener("click",function(){setMacro(v);});
    el.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();setMacro(v);}});
  })(mbs[m]);}
  var lb=root.querySelector('[data-toggle="links"]');
  if(lb){
    function setLinks(on){ if(on){root.classList.add("az-showlinks");lb.setAttribute("data-on","1");lb.setAttribute("aria-pressed","true");if(live)live.textContent="Ligações micro-macro visíveis: beta-amiloide leva às placas corticais, tau aos emaranhados, a degeneração à atrofia e o hipocampo à amnésia recente.";} else {root.classList.remove("az-showlinks");lb.removeAttribute("data-on");lb.setAttribute("aria-pressed","false");} }
    lb.addEventListener("click",function(){setLinks(!root.classList.contains("az-showlinks"));});
    lb.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();setLinks(!root.classList.contains("az-showlinks"));}});
  }
  setMacro(root.getAttribute("data-macro")||"alz");
})();
/**/
